          const m = c[0].match(/^(?:(\d{2})\/(\d{2})|(\d{4}))$/);
          if (!m) continue;
          const season = m[3] || (m[1] + "/" + m[2]);
          if (seasons.some(s2 => s2.id.split("/")[0] === dir && s2.season === season)) continue;
