                      <th style={{ ...thCell, textAlign: "center" }}>GP</th>
                      {STAT_COLS.map(c => <th key={c} style={{ ...thCell, textAlign: "center" }}>{c}</th>)}
                      <th style={{ ...thCell, textAlign: "center" }}>RTG</th>
